<template><a-config-provider :locale="locale"><div class="design-root">
<div class="design-note"><b>B · #1464 개선 UI 목업</b><span>설계 예시 · 준비 완료/부분 반영은 합성 · 실제 확장 실행 아님</span><a-button size="small" @click="open('create')">신규 생성</a-button><a-button size="small" @click="open('blocked')">기존 VM 차단</a-button><a-button size="small" @click="open('ready')">지원 조건 예시</a-button><a-button size="small" @click="open('recovery')">복구 필요</a-button><a-switch v-model:checked="dark" checked-children="다크" un-checked-children="라이트"/></div>
<div class="shell"><aside><b>ABLESTACK</b><p>대시보드</p><p>컴퓨트　⌄</p><p>　가상머신</p><p>스토리지　⌄</p><div class="selected">공유 파일 시스템</div><p>네트워크</p><p>이미지</p></aside><div class="workspace"><header><span>☰　기본 보기</span><span>AC　admin cloud</span></header>
<a-card class="breadcrumb-card"><a-row align="middle"><a-col :span="18"><Breadcrumb :resource="{name:'sharedfs-compute-design'}"><template #end><a-button size="small" shape="round"><ReloadOutlined/>업데이트</a-button></template></Breadcrumb></a-col><a-col :span="6" class="right"><a-dropdown :trigger="['click']"><a-button>작업 <DownOutlined/></a-button><template #overlay><a-menu><a-menu-item @click="open('blocked')">컴퓨트 확장</a-menu-item><a-menu-item @click="open('recovery')">확장 작업 상태</a-menu-item></a-menu></template></a-dropdown></a-col></a-row></a-card>
<main><ResourceLayout><template #left><a-card class="info"><FileTextOutlined class="icon"/><h3>sharedfs-compute-design</h3><a-badge status="success" text="사용 가능"/><dl><dt>주 IP</dt><dd>10.10.13.227 (예시)</dd><dt>CPU / 메모리</dt><dd>2 CPU · 4 GiB</dd><dt>볼륨</dt><dd>ROOT 10 GiB · DATA 12 GiB · SPARSE</dd><dt>프로토콜</dt><dd>NFS · SMB · iSCSI · NVMe-oF</dd></dl></a-card></template>
<template #right><a-card class="tab-card"><a-tabs v-model:activeKey="tab" tab-position="left"><a-tab-pane key="details" tab="상세"><a-list size="small" :data-source="details"><template #renderItem="{item}"><a-list-item><div class="detail"><strong>{{item[0]}}</strong><span>{{item[1]}}</span></div></a-list-item></template></a-list></a-tab-pane><a-tab-pane key="capacity" tab="용량·볼륨"/><a-tab-pane key="directory" tab="공유 디렉터리"/><a-tab-pane key="nfs" tab="NFS"/><a-tab-pane key="smb" tab="SMB"/><a-tab-pane key="iscsi" tab="iSCSI"/><a-tab-pane key="nvme" tab="NVMe-oF"/><a-tab-pane key="backup" tab="구성 백업"/><a-tab-pane key="runtime" tab="런타임"/><a-tab-pane key="boot" tab="부팅 복구"/><a-tab-pane key="network" tab="네트워크"/><a-tab-pane key="operations" tab="작업 내역"/></a-tabs></a-card></template></ResourceLayout></main></div></div>
<MoldDialog :visible="!!dialog" :title="dialog==='create'?'공유 파일 시스템 생성 · 컴퓨트 조건':dialog==='recovery'?'컴퓨트 확장 작업 진단':'컴퓨트 확장'" size="lg" @cancel="dialog=''"><div class="compute-body">
<template v-if="dialog==='recovery'"><a-alert type="warning" show-icon message="메모리는 연결됐지만 게스트 반영이 확인되지 않았습니다. (설계 예시)" description="실패 원인을 보존하고 자원 예약·서비스 변경 잠금을 유지합니다. 자동 메모리 제거·축소·VM 재시작을 실행하지 않습니다."/>
<a-descriptions bordered :column="1" size="small" class="spaced"><a-descriptions-item label="작업 식별자">동일 작업 UUID (예시)</a-descriptions-item><a-descriptions-item label="단계">GUEST_ONLINE → OBSERVATION_PENDING</a-descriptions-item><a-descriptions-item label="최초 원인">COMPUTE_GUEST_OBSERVATION_UNAVAILABLE</a-descriptions-item><a-descriptions-item label="동일 요청">새 장치를 중복 연결하지 않고 실제 상태를 재관측</a-descriptions-item></a-descriptions>
<a-table size="small" class="spaced" row-key="name" :columns="resourceColumns" :data-source="recoveryResources" :pagination="false"/><p class="hint">VM DB·SharedFS DB·할당 자원·게스트 온라인 자원을 구분합니다. 승인 범위를 벗어나거나 신원이 바뀌면 같은 작업 재개도 차단합니다.</p>
<a-table size="small" class="spaced" row-key="name" :columns="checkColumns" :data-source="[{name:'DATA UUID·크기·마운트·권한',state:'보존',reason:'저장소 설정 변경 없음 (예시)'},{name:'writer / 용량 예약',state:'유지',reason:'불확실한 성공을 확정하지 않음'},{name:'후속 처리',state:'관측 필요',reason:'명확한 상태 확인 후 같은 승인 목표만 이어하기'}]" :pagination="false"/></template>
<template v-else-if="dialog==='create'"><a-alert show-icon type="info" message="신규 서비스는 온라인 CPU·메모리 확장 조건을 충족해야 합니다." description="오퍼링뿐 아니라 zone·선택 SystemVM 템플릿·검증된 하이퍼바이저 조합을 서버가 확인합니다. 고정·자유·범위·부분 커스텀 입력은 유지합니다."/>
<a-form layout="vertical" class="spaced"><a-form-item label="Zone"><a-input value="13-Zone (예시)" disabled/></a-form-item><a-form-item label="컴퓨트 오퍼링"><a-select v-model:value="offering"><a-select-option value="dynamic">사용자 정의 · HA · 동적 확장 (조건부 선택)</a-select-option><a-select-option value="fixed" disabled>기존 고정2C4G · 동적 확장 꺼짐 — 선택 불가</a-select-option><a-select-option value="thin" disabled>4C8G · ROOT THIN — 선택 불가</a-select-option><a-select-option value="range">범위/부분 커스텀 · HA · 동적 확장 (예시)</a-select-option></a-select></a-form-item>
<a-row :gutter="12"><a-col :span="8"><a-form-item label="CPU"><a-input-number v-model:value="cpu" :min="2"/></a-form-item></a-col><a-col :span="8"><a-form-item label="메모리 (MiB)"><a-input-number v-model:value="memory" :min="1024"/></a-form-item></a-col><a-col :span="8"><a-form-item label="CPU 속도 (MHz)"><a-input-number :value="2000" disabled/></a-form-item></a-col></a-row></a-form>
<a-alert show-icon type="error" message="현재 선택되는 SystemVM 템플릿은 동적 확장을 지원하도록 준비되지 않았습니다." description="TEMPLATE_DYNAMIC_DISABLED · 다른 검증된 준비 템플릿이 제공되기 전에는 새 서비스 생성을 진행할 수 없습니다. 기존 서비스는 유지됩니다."/>
<a-table size="small" class="spaced" row-key="name" :columns="checkColumns" :data-source="checks" :pagination="false"/>
<p class="hint">이 목업은 생성 폼의 컴퓨트 조건 변경 부분입니다. 기존 네트워크·ROOT/DATA·파일시스템·SPARSE 및 이어하기 입력은 그대로 유지합니다.</p></template>
<template v-else><a-alert show-icon :type="dialog==='ready'?'info':'warning'" :message="dialog==='ready'?'한 번에 CPU 또는 메모리 한 축만 늘립니다. (조건 충족 설계 예시)':'현재 VM은 온라인 확장 준비가 필요합니다.'" :description="dialog==='ready'?'실행 중 기존 세션은 유지합니다. 적용 전 현재 host·VM·게스트·예약 상태와 승인 목표를 다시 검증합니다.':'zone·오퍼링 플래그는 켜져 있지만 템플릿/VM 플래그와 실제 hotplug 여유가 없습니다. 게스트 재부팅만으로 해결되지 않습니다.'"/>
<a-descriptions bordered :column="2" size="small" class="spaced"><a-descriptions-item label="현재 CPU / 메모리">2 CPU / 4096 MiB</a-descriptions-item><a-descriptions-item label="현재 상태">Running · SPARSE ROOT/DATA</a-descriptions-item><a-descriptions-item label="현재 ROOT">UUID·크기·정책 보존</a-descriptions-item><a-descriptions-item label="네트워크 / 프로토콜">기존 IP·MAC·설정 보존</a-descriptions-item></a-descriptions>
<a-form layout="vertical" class="spaced"><a-form-item label="확장 방식"><a-radio-group v-model:value="axis"><a-radio value="cpu">CPU 확장</a-radio><a-radio value="memory">메모리 확장</a-radio></a-radio-group></a-form-item><a-form-item label="대상 오퍼링"><a-select v-model:value="offering"><a-select-option value="dynamic">기존 ROOT 정책과 호환되는 동적 오퍼링 (예시)</a-select-option><a-select-option value="range">범위·부분 커스텀 (예시)</a-select-option></a-select></a-form-item>
<a-row :gutter="12"><a-col :span="8"><a-form-item label="목표 CPU"><a-input-number v-model:value="cpu" :disabled="axis!=='cpu'" :min="2"/></a-form-item></a-col><a-col :span="8"><a-form-item label="목표 메모리 (MiB)"><a-input-number v-model:value="memory" :disabled="axis!=='memory'" :min="4096" :step="128"/></a-form-item></a-col><a-col :span="8"><a-form-item label="CPU 속도"><a-input value="2000 MHz · 유지" disabled/></a-form-item></a-col></a-row></a-form>
<a-alert v-if="bothChanged" type="error" show-icon message="CPU와 메모리 동시 변경은 지원하지 않습니다. 한 축씩 확장하세요."/>
<a-table size="small" class="spaced" row-key="name" :columns="checkColumns" :data-source="checks" :pagination="false"/>
<a-alert v-if="dialog==='blocked'" class="spaced" type="warning" show-icon message="기존 인스턴스 전환 안내" description="현재 템플릿이 준비되지 않아 전환이 차단됩니다. 검증된 템플릿이 있는 경우에만 정상 정지 → 호환 오퍼링·VM 준비 → 완전한 새 시작 → XML·게스트 검증을 진행합니다. 템플릿 교체·DATA 보존 이동은 기존 별도 절차를 이용합니다."/>
<a-alert v-if="dialog==='ready' && planReady" class="spaced" type="success" show-icon message="사전 점검 READY · 승인 지문과 유효 시간 확인 (설계 예시)"/>
<a-checkbox v-if="dialog==='ready' && planReady" class="spaced" v-model:checked="ack">온라인 확장의 일시적인 성능 영향과 승인된 변경 범위를 확인했습니다.</a-checkbox>
<p class="hint">사전 점검이 유효한 동안에만 같은 VM·host·대상·ROOT/템플릿 신원으로 적용합니다. 온라인 축소·ROOT 변경·호스트 자동 마이그레이션은 지원하지 않습니다.</p></template>
<a-alert v-if="notice" class="spaced" type="info" show-icon message="설계 목업입니다. 실제 요청이나 자원 변경을 실행하지 않습니다."/></div>
<template #footer><a-button @click="dialog=''">{{dialog==='recovery'?'닫기':'취소'}}</a-button><a-button v-if="dialog==='recovery'" @click="notice=true">관측 업데이트</a-button><a-button v-if="dialog==='recovery'" type="primary" @click="notice=true">같은 작업 상태 확인</a-button><a-button v-else type="primary" :disabled="dialog!=='ready'||(planReady&&!ack)||bothChanged" @click="preview">{{dialog==='create'?'생성':dialog==='ready'?(planReady?'온라인 확장':'사전 점검'):'준비 필요'}}</a-button></template></MoldDialog>
</div></a-config-provider></template>
<script>
import koKR from 'ant-design-vue/es/locale/ko_KR'
import Breadcrumb from '@/components/widgets/Breadcrumb.vue'
import ResourceLayout from '@/layouts/ResourceLayout.vue'
import MoldDialog from '@/components/view/MoldDialog.vue'
import {ReloadOutlined,DownOutlined,FileTextOutlined} from '@ant-design/icons-vue'
const q=new URLSearchParams(location.search)
export default {components:{Breadcrumb,ResourceLayout,MoldDialog,ReloadOutlined,DownOutlined,FileTextOutlined},data(){return {locale:koKR,dark:q.get('theme')==='dark',dialog:q.get('dialog')||'',tab:'details',offering:'dynamic',axis:'cpu',cpu:4,memory:4096,ack:false,planReady:false,notice:false,
checkColumns:[{title:'지원 조건',dataIndex:'name',width:180},{title:'판정',dataIndex:'state',width:120},{title:'근거 / 조치',dataIndex:'reason'}],
resourceColumns:[{title:'자원',dataIndex:'name'},{title:'승인 전',dataIndex:'before'},{title:'목표 / 할당',dataIndex:'allocated'},{title:'게스트 관측',dataIndex:'observed'}],
recoveryResources:[{name:'CPU',before:'2',allocated:'2',observed:'2 online (예시)'},{name:'메모리',before:'4096 MiB',allocated:'8192 MiB',observed:'조회 불가 · 재관측 필요 (예시)'}]}},
watch:{dark:{immediate:true,handler(v){document.body.classList.toggle('dark-mode',v)}},axis(v){this.cpu=v==='cpu'?4:2;this.memory=v==='memory'?8192:4096},cpu(){this.planReady=false;this.ack=false},memory(){this.planReady=false;this.ack=false},offering(){this.planReady=false;this.ack=false}},
computed:{bothChanged(){return this.cpu>2&&this.memory>4096},details(){return [['이름','sharedfs-compute-design'],['상태','Ready'],['CPU / 메모리','2 CPU / 4096 MiB'],['온라인 확장','준비 필요 · 템플릿/VM/XML 조건 불충족'],['프로비저닝','SPARSE'],['Zone','13-Zone']]},checks(){const ready=this.dialog==='ready';return [{name:'Zone 동적 확장',state:'PASS',reason:'enable.dynamic.scale.vm=true'},{name:'오퍼링 · HA/ROOT',state:'PASS',reason:'동적 플래그 true · HA · SPARSE'},{name:'선택 템플릿',state:ready?'PASS (예시)':'BLOCKED',reason:ready?'검증된 compute profile (예시)':'isdynamicallyscalable=false (현재 관측)'},{name:'VM / live XML',state:ready?'PASS (예시)':'준비 필요',reason:ready?'vCPU·maxMemory·DIMM slots 여유 (합성)':'VM flag=false · vCPU max=2 · maxMemory 없음'},{name:'게스트 반영',state:ready?'지원 (예시)':'준비 필요',reason:ready?'검증 helper가 승인된 신규 블록만 온라인':'memory auto_online_blocks=offline (현재 관측)'},{name:'변경 범위',state:this.bothChanged?'BLOCKED':'단일 축',reason:'CPU/메모리 축소·동시 변경·ROOT/host 변경 차단'},{name:'진행 중 작업 / 용량',state:ready?(this.planReady?'READY (예시)':'점검 필요'):'미점검',reason:'서버가 잠금·현재 host 여유·예약을 재검증'}]}},
methods:{preview(){if(!this.planReady)this.planReady=true;else this.notice=true},open(kind){this.dialog=kind;this.notice=false;this.ack=false;this.planReady=false;this.cpu=kind==='create'?2:4;this.memory=4096}}}
</script>
<style>
.design-root{min-height:100vh;background:var(--ui-bg-page);color:var(--ui-text-primary)}.design-note{display:flex;align-items:center;gap:8px;padding:10px 16px;background:var(--ui-bg-elevated);border-bottom:1px solid var(--ui-border);font-size:12px}.design-note>span{flex:1;color:var(--ui-text-secondary)}.shell{display:flex;min-height:calc(100vh - 50px)}aside{width:200px;flex-shrink:0;padding:20px 16px;background:var(--ui-bg-elevated);border-right:1px solid var(--ui-border)}aside>b{font-size:26px}aside p{margin:28px 8px}.selected{padding:12px;background:var(--ui-bg-selected);color:var(--ui-link);border-radius:4px}.workspace{flex:1;min-width:0}header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:var(--ui-bg-elevated);border-bottom:1px solid var(--ui-border)}.breadcrumb-card{border-radius:0}.breadcrumb-card>.ant-card-body{padding:16px 24px}.right{text-align:right}main{padding:16px 24px}.info h3{overflow-wrap:anywhere;color:var(--ui-text-primary);margin:16px 0}.icon{font-size:36px;color:var(--ui-link)}dt{font-weight:600;margin:16px 0 4px}dd{margin:0}.tab-card>.ant-card-body{padding:16px}.tab-card .ant-tabs-nav{min-width:112px}.spaced{margin-top:16px}.hint{font-size:12px;line-height:1.8;color:var(--ui-text-secondary);margin:12px 0}.detail{display:flex;flex-direction:column;gap:8px;width:100%;padding:4px 0}.detail strong{color:var(--ui-text-secondary)}.compute-body{color:var(--ui-text-primary)}@media(max-width:1000px){aside{display:none}main{padding:16px}.design-note>span{display:none}}
</style>
